#pragma once

// QR codes made once by the reference encoder qrcodegen 1.8.0 (Project
// Nayuki, MIT licence) for the tests of QrCode.cpp. Each code with a fixed
// mask was made by segno 1.6.6 too and came out the same (but where segno
// writes a zero byte after a terminator that ends on a byte, a bug of that
// version, where the standard has a pad codeword), and each code of text
// read back as its text in OpenCV 5's QR decoder. Each case: the
// bytes in byte mode, the
// level asked for, the mask (-1: the penalty rules' pick) and boost; then the
// version, level and mask that came out, and the modules a row at a time from
// the top, four to a hex digit, dark as 1 (up to version 10), or FNV-1a's
// 64-bit hash of the modules as bytes of 0 and 1 (larger codes).

struct QrReference {
	const char *pBytes;		// or 0: MadeBytes(Count, Seed)
	int Count, Seed;
	size_t Length;
	char Level;
	int Mask;
	bool Boost;
	int Version;
	char MadeLevel;
	int MadeMask;
	unsigned long long Hash;
	const char *pModules;
};

